    assertQuestSafeUnlitMaterialRenderCallbacks(mat);
    assert.equal(mat.stencilWrite, false, "prior stencilWrite pin stays false");
    assert.equal(mat.stencilRef, 0, "prior stencilRef pin stays 0");
