  interleavedGeo.setAttribute("position", new THREE.InterleavedBufferAttribute(interleavedBuffer, 3, 0));
  interleavedGeo.setIndex([0, 1, 2]);
  const interleavedMat = new THREE.MeshBasicMaterial({ color: 0x633318 });
